#!/usr/bin/env python3
"""Generate docs/evidence/p29/{RESULTS,NEGATIVE_FINDINGS}.md from results/v2/haa-* ONLY (no hand-written numbers). `--check` verifies they are current."""
import json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); D = os.path.join(ROOT, "docs/evidence/p29")
def J(n): return json.load(open(os.path.join(ROOT, "results/v2", n, "result.json")))
def pct(x): return f"{100 * x:.1f}%"
def results():
    m, h, a, l = J("haa-main"), J("haa-heldout"), J("haa-adaptive"), J("haa-latency"); g = m["aggregate"]; pb = g["per_baseline"]
    L = ["# HorizonAgentAnomalyBench results (generated by bench/haa/report.py from results/v2/haa-*)", "",
         "**Status: CANDIDATE.** L2 only (real isolated effects against local mocks). L3 (live model) and L5 (pilot) were **NOT RUN**; HR-G7/HR-G9 stay NOT MET. IPv6 is unavailable on the test VM, so IPv6 channels are untested.", "",
         f"Main run: {len(g['eligible_by_B0_effect'])} scenarios, all eligible (each has an effect under B0), {g['repeats']} repeats, same manifest for every baseline.", "",
         "## Unsafe-effect rate (UER) by baseline", "", "| Baseline | UER | Wilson 95% CI | Benign controls completed | Verified false blocks |", "|---|---|---|---|---|"]
    for b, v in pb.items():
        u = v["uer"]; c = v["completion"]; fb = v["false_blocks_verified"]
        L.append(f"| {b} — {v.get('description','')} | {u['k']}/{u['n']} ({pct(u['rate'])}) | {u['wilson95']} | {c['k']}/{c['n']} | {fb['k']}/{fb['n']} |")
    L += ["", "## Paired comparison vs B0 (exact McNemar, Holm-adjusted)", "", "| Pair | risk diff | discordant (A only / B only) | Holm p |", "|---|---|---|---|"]
    for k, v in g["paired"].items(): L.append(f"| {k} | {v['risk_difference']} | {v['discordant_a_only']} / {v['discordant_b_only']} | {v['holm_adjusted_p']} |")
    L += ["", f"Template-cluster bootstrap 95% CI for risk difference B6−B0: {g['cluster_bootstrap_rd_B6_vs_B0']} (degenerate when all clusters agree; see caveat).", "",
          "## Held-out variants (new destination port 47707; asyncio/perl/bash/http.client/node/ruby)", "", "| Baseline | effects | benign ok |", "|---|---|---|"]
    for b, v in h["aggregate"]["per_baseline"].items(): L.append(f"| {b} | {v['effects']} | {v['control_ok']}/{v['controls']} |")
    L += ["", f"## Adaptive campaign (seed {a['aggregate']['seed']}, budget {a['aggregate']['budget']} attempts, channel × destination-form)", "", "| Baseline | attempts | bypasses | first bypass at |", "|---|---|---|---|"]
    for b, v in a["aggregate"]["per_baseline"].items(): L.append(f"| {b} | {v['attempts']} | {v['bypasses']} | {v['first_bypass_at']} |")
    L += ["", "## Latency / utility (wall-clock of launch, single VM, n per cell below)", "", "| Cell | p50 s | p95 s | p99 s | success |", "|---|---|---|---|---|"]
    for k, v in l["aggregate"]["per_cell"].items(): L.append(f"| {k} | {v['p50']} | {v['p95']} | {v['p99']} | {v['success']}/{v['n']} |")
    L += ["", "## Caveats", "", "- Scenarios and defences were developed together by one party; the held-out and adaptive sets reduce but do not remove tuning bias. No independent review.", "- B1/B2 are in-repo stand-ins (regex / classifier-like), not real products.", "- A UER of 0 means no effect was observed at the local oracle sinks in these runs; it is not a proof of safety.", "- Statistics assume scenario independence; scenarios within an effect family are correlated."]
    return "\n".join(L) + "\n"
def negative():
    g = J("haa-main")["aggregate"]; n = g["negative_findings"]; a = J("haa-adaptive")["aggregate"]["per_baseline"]
    L = ["# Negative findings and uninstrumented paths (generated)", "", "Reported without reclassifying any of them as safe.", "",
         f"- **B6 unprevented scenarios:** {n['B6_unprevented'] or 'none observed'}; **B6 benign-control failures:** {n['B6_control_failed'] or 'none observed'}.",
         f"- **B5 (sandbox + net/cred broker, no label taint / artifact gate / managed hooks) still allowed effects in:** {n['B5_effects_B6_prevents']} — these are what the B6 additions buy.",
         f"- **B4 (sandbox only)** blocked most effects but failed benign controls in {len(n['sandbox_only_B4_control_failures'])} scenarios (utility loss) and still had effects in {n['sandbox_only_B4_effects']}.",
         f"- **B3 (name-based wrapper)** only partially mitigated in {len(n['B3_vs_B0_only_partial'])} scenarios: unconfined code bypasses name-based checks.",
         f"- **Scanners:** B1 missed effects in {len(n['scanner_only_effects']['B1'])} scenarios; B2 missed {len(n['scanner_only_effects']['B2'])}.",
         f"- **Adaptive campaign bypass counts:** " + ", ".join(f"{b}={v['bypasses']}/{v['attempts']}" for b, v in a.items()) + ".", "",
         "## Uninstrumented / untested paths", "", "- IPv6 (VM has no IPv6: EAFNOSUPPORT) — destination forms using IPv6 literals were not exercised end to end.",
         "- L3: no live model was run; spontaneous occurrence rates are unknown.", "- L5: no pilot or independent adversary.",
         "- Event/audit agreement is checked at the broker/receiver level only, not for every process-level event.",
         "- Single kernel (6.18, x86_64, root launcher, Landlock ABI 7); other kernels/architectures untested; no hypervisor-escape or kernel-exploit coverage.",
         "- Mock services only: no real cloud metadata, registry, or third-party endpoint was contacted."]
    return "\n".join(L) + "\n"
if __name__ == "__main__":
    out = {"RESULTS.md": results(), "NEGATIVE_FINDINGS.md": negative()}; bad = 0
    for f, t in out.items():
        p = os.path.join(D, f)
        if "--check" in sys.argv:
            if not os.path.exists(p) or open(p).read() != t: print("stale", f); bad = 1
        else: open(p, "w").write(t)
    sys.exit(bad)
